        const match = CHART_SPEC.transitions.find((t) => t.from === current && t.event === eventName && guardAllows(t));
        if (!match) return false;
        if (eventName === 'Retry') retries += 1;
        current = match.to;
        const rule = CHART_SPEC.rules.find((r) => r.from === match.from && r.event === match.event && r.to === match.to);
        lastRuleId = rule ? rule.id : null;
        render();
        return true;
      }

      function jumpToState(stateId) {
        const target = CHART_SPEC.states.find((s) => s.id === stateId);
        if (!target) return;
        const via = CHART_SPEC.transitions.find((t) => t.from === current && t.to === stateId && guardAllows(t));
        if (via && via.event === 'Retry') retries += 1;
        current = stateId;
        lastRuleId = via ? (CHART_SPEC.rules.find((r) => r.from === via.from && r.to === via.to)?.id ?? null) : null;
        render();
      }

      function renderTriggers() {
        triggersEl.querySelectorAll('button').forEach((b) => b.remove());
        const available = CHART_SPEC.transitions.filter((t) => t.from === current && guardAllows(t));
        const allEvents = [...new Set(CHART_SPEC.transitions.map((t) => t.event))];
        allEvents.forEach((ev) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'tc-btn';
          btn.textContent = ev;
          btn.disabled = !available.some((t) => t.event === ev);
          btn.addEventListener('click', () => { stopPlay(); fireEvent(ev); });
          triggersEl.appendChild(btn);
        });
      }

      function renderStage() {
        document.querySelectorAll('[data-state-node]').forEach((node) => {
          const id = node.getAttribute('data-state-node');
          const active = id === current;
          node.setAttribute('data-active', String(active));
          node.setAttribute('aria-pressed', String(active));
          const box = node.querySelector('.tc-box');
          if (box) box.setAttribute('fill', active ? 'var(--tc-accent-soft)' : 'var(--tc-surface)');
        });
        document.querySelectorAll('.tc-edge').forEach((edge) => {
          const tr = CHART_SPEC.transitions.find((t) => t.id === edge.dataset.edgeId);
          const active = Boolean(tr && tr.from === current && guardAllows(tr));
          edge.setAttribute('data-active', String(active));
        });
      }

      function renderRules() {
        rulesEl.innerHTML = '';
        CHART_SPEC.rules.forEach((r) => {
          const li = document.createElement('li');
          li.className = 'tc-rule';
          li.dataset.active = String(r.id === lastRuleId || r.from === current);
          li.innerHTML = `<span class="tc-rule-id">${r.id}</span><strong>${r.from} → ${r.to}</strong> (${r.event} · ${r.guard})<br><span style="color:var(--tc-muted)">${r.text}</span>`;
          rulesEl.appendChild(li);
        });
      }

      function logicEdgePath(t) {
        const a = stateById(t.from);
        const b = stateById(t.to);
        const halfW = 52;
        const halfH = 18;
        if (t.from === 'authorizing' && t.to === 'declined') {
          return `M ${a.x + 12} ${a.y + halfH} L ${b.x + 12} ${b.y - halfH - 2}`;
        }
        if (t.from === 'declined' && t.to === 'authorizing') {
          return `M ${a.x - 12} ${a.y - halfH} L ${b.x - 12} ${b.y + halfH + 2}`;
        }
        if (a.y === b.y) {
          const dir = a.x < b.x ? 1 : -1;
          return `M ${a.x + dir * halfW} ${a.y} L ${b.x - dir * (halfW + 2)} ${b.y}`;
        }
        const vdir = a.y < b.y ? 1 : -1;
        return `M ${a.x} ${a.y + vdir * halfH} L ${b.x} ${b.y - vdir * (halfH + 2)}`;
      }

      function renderLogicFlowchart() {
        const ns = 'http://www.w3.org/2000/svg';
        logicSvg.querySelectorAll('.tc-lf-dyn').forEach((n) => n.remove());
        const g = document.createElementNS(ns, 'g');
        g.setAttribute('class', 'tc-lf-dyn');

        CHART_SPEC.transitions.forEach((t) => {
          const active = t.from === current && guardAllows(t);
          const p = document.createElementNS(ns, 'path');
          p.setAttribute('d', logicEdgePath(t));
          p.setAttribute('fill', 'none');
          p.setAttribute('stroke', active ? 'var(--tc-accent)' : 'var(--tc-border-strong)');
          p.setAttribute('stroke-width', active ? '2.2' : '1.4');
          p.setAttribute('marker-end', active ? 'url(#tc-lf-arrow-active)' : 'url(#tc-lf-arrow)');
          g.appendChild(p);
        });

        CHART_SPEC.states.forEach((s) => {
          const active = s.id === current;
          const rect = document.createElementNS(ns, 'rect');
          rect.setAttribute('x', String(s.x - 52));
          rect.setAttribute('y', String(s.y - 18));
          rect.setAttribute('width', '104');
          rect.setAttribute('height', '36');
          rect.setAttribute('rx', '8');
          rect.setAttribute('fill', active ? 'var(--tc-accent-soft)' : 'var(--tc-surface)');
          rect.setAttribute('stroke', active ? 'var(--tc-accent)' : 'var(--tc-border-strong)');
          rect.setAttribute('stroke-width', active ? '2.2' : '1.3');
          g.appendChild(rect);

          const txt = document.createElementNS(ns, 'text');
          txt.setAttribute('x', String(s.x));
          txt.setAttribute('y', String(s.y + 4));
          txt.setAttribute('text-anchor', 'middle');
          txt.setAttribute('font-size', '11');
          txt.setAttribute('font-weight', active ? '700' : '600');
          txt.setAttribute('fill', 'var(--tc-text)');
          txt.textContent = s.label;
          g.appendChild(txt);
        });

        logicSvg.appendChild(g);
      }

      function render() {
        const st = stateById(current);
        stateLabelEl.textContent = st.label;
        stepDescEl.textContent = current === 'declined' && retries >= 2
          ? 'Max retries (2 / 2) reached; only Cancel is available.'
          : st.summary;
        retriesEl.textContent = `Retries used: ${retries} / 2`;
        renderTriggers();
        renderStage();
        renderRules();
        renderLogicFlowchart();
      }

      function stopPlay() {
        if (playTimer) { clearInterval(playTimer); playTimer = null; }
        playBtn.setAttribute('aria-pressed', 'false');
        playBtn.textContent = 'Play';
      }

      function resetAll() {
        stopPlay();
        current = CHART_SPEC.initialState;
        retries = 0;
        lastRuleId = null;
        demoIndex = 0;
        render();
      }

      function stepOnce() {
        if (current === 'confirmed' || current === 'cancelled') { resetAll(); return; }
        for (let i = 0; i < CHART_SPEC.demoSequence.length; i++) {
          const ev = CHART_SPEC.demoSequence[(demoIndex + i) % CHART_SPEC.demoSequence.length];
          if (fireEvent(ev)) { demoIndex = (demoIndex + i + 1) % CHART_SPEC.demoSequence.length; return; }
        }
        const first = CHART_SPEC.transitions.find((t) => t.from === current && guardAllows(t));
        if (first) fireEvent(first.event);
      }

      playBtn.addEventListener('click', () => {
        if (playTimer) { stopPlay(); return; }
        playBtn.setAttribute('aria-pressed', 'true');
        playBtn.textContent = 'Pause';
        stepOnce();
        playTimer = setInterval(stepOnce, 1400);
      });

      stepBtn.addEventListener('click', () => { stopPlay(); stepOnce(); });
      resetBtn.addEventListener('click', resetAll);

      logicBtn.addEventListener('click', () => {
        const next = logicBtn.getAttribute('aria-expanded') !== 'true';
        logicBtn.setAttribute('aria-expanded', String(next));
        drawer.hidden = !next;
      });

      const darkQuery = window.matchMedia('(prefers-color-scheme: dark)');
      function currentTheme() {
        const explicit = document.documentElement.dataset.theme;
        if (explicit === 'dark' || explicit === 'light') return explicit;
        return darkQuery.matches ? 'dark' : 'light';
      }
      function syncTheme() {
        const isDark = currentTheme() === 'dark';
        themeBtn.setAttribute('aria-pressed', String(isDark));
        themeBtn.textContent = isDark ? 'Light mode' : 'Dark mode';
      }
      themeBtn.addEventListener('click', () => {
        document.documentElement.dataset.theme = currentTheme() === 'dark' ? 'light' : 'dark';
        syncTheme();
      });
      syncTheme();

      document.querySelectorAll('[data-state-node]').forEach((node) => {
        const id = node.getAttribute('data-state-node');
        node.addEventListener('click', () => { stopPlay(); jumpToState(id); });
        node.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault(); stopPlay(); jumpToState(id);
          }
        });
      });

      render();
    })();
  </script>
</body>
</html>
```

**Playable Controls & Logic Summary**
- **Declarative `CHART_SPEC`:** Models the 6 states (`cart` → `authorizing` → `challenge` → `confirmed`, plus `declined` and `cancelled`) and 6 guarded transitions (`Submit`, `Require 3DS`, `Verify OTP`, `Card Declined`, `Retry` with `retries < 2`, and `Cancel`).
- **Interactive controls:** `Play`, `Step`, `Reset`, live event trigger buttons (`Submit`, `Require 3DS`, `Verify OTP`, `Card Declined`, `Retry`, `Cancel`), clickable/keyboard-focusable state nodes, an `aria-live="polite"` status readout, and a retry counter (`Retries used: 0 / 2`) that disables `Retry` once 2 retries are reached.
- **Light/Dark & Show the logic:** Supports system `prefers-color-scheme: dark`, a manual `Dark mode` / `Light mode` toggle, `@media (prefers-reduced-motion: reduce)`, and a `Show the logic` (`aria-expanded`) drawer synchronizing the highlighted Rules list (`R1`–`R6`) and mini Logic Flowchart SVG with the active state.
